parameters.jsCode:
const event = $json.event_type;
const biz = $json.business_name || 'Our Business';
const name = $json.customer_name;
const phone = $json.customer_phone;
const time = $json.appointment_time;

// Each Meta-approved template has its own variable order/count
const templates = {
  booking_confirmed: { name: 'apptbook_confirmed', params: [name, biz, time] },
  appointment_reminder: { name: 'apptbook_reminder', params: [name, biz, time] },
  booking_completed: { name: 'apptbook_completed', params: [name, biz] },
  booking_cancelled: { name: 'apptbook_cancelled', params: [name, biz, time] },
  cancellation_requested: { name: 'apptbook_cancel_request', params: [name, time] },
  cancellation_rejected: { name: 'apptbook_cancel_declined', params: [name, biz, time] }
};

const ownerSubjects = {
  booking_confirmed: `New booking confirmed - ${name}`,
  appointment_reminder: `Reminder due - ${name}`,
  booking_completed: `Booking completed - ${name}`,
  booking_cancelled: `Booking cancelled - ${name}`,
  cancellation_requested: `ACTION NEEDED: ${name} wants to cancel - approve or reject in the dashboard`,
  cancellation_rejected: `Cancellation rejected - ${name} stays booked`
};

const tpl = templates[event] || templates.booking_confirmed;

return [{
  json: {
    ...$json,
    whatsapp_template: tpl.name,
    whatsapp_params: tpl.params,
    owner_subject: ownerSubjects[event] || `Booking update - ${name}`,
    owner_body: `Event: ${event}\nCustomer: ${name}\nPhone: ${phone}\nAppointment: ${time}`
  }
}];

parameters.jsonBody:
={{ {
  messaging_product: "whatsapp",
  to: $json.customer_phone,
  type: "template",
  template: {
    name: $json.whatsapp_template,
    language: { code: "en_US" },
    components: [
      {
        type: "body",
        parameters: $json.whatsapp_params.map(p => ({ type: "text", text: String(p) }))
      }
    ]
  }
} }}
